import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

public class ThumbnailCreator {
    public static void main(String[] args) {
        try {
            // Load the image
            BufferedImage image = ImageIO.read(new File("image.jpg"));

            // Create a thumbnail
            BufferedImage thumbnail = createThumbnail(image, 100, 100);

            // Save the thumbnail
            ImageIO.write(thumbnail, "jpg", new File("thumbnail.jpg"));
        } catch (IOException e) {
            System.out.println("Error creating thumbnail: " + e.getMessage());
        }
    }

    public static BufferedImage createThumbnail(BufferedImage image, int width, int height) {
        // Calculate the aspect ratio of the image
        double aspectRatio = (double) image.getWidth() / image.getHeight();

        // Calculate the new width and height of the thumbnail
        int newWidth = (int) (height * aspectRatio);
        int newHeight = height;

        // Create a new thumbnail image
        BufferedImage thumbnail = new BufferedImage(newWidth, newHeight, BufferedImage.TYPE_INT_RGB);

        // Draw the original image onto the thumbnail
        Graphics2D g2d = thumbnail.createGraphics();
        g2d.drawImage(image, 0, 0, newWidth, newHeight, null);
        g2d.dispose();

        return thumbnail;
    }
}
